import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Headless & scripting","description":"prioricode run for CI and pipes — message arguments, --format json events, file attachments, attach mode, and non-interactive permission behavior.","frontmatter":{"title":"Headless & scripting","description":"prioricode run for CI and pipes — message arguments, --format json events, file attachments, attach mode, and non-interactive permission behavior."},"headers":[],"relativePath":"using/headless.md","filePath":"using/headless.md"}'),n={name:"using/headless.md"};function o(h,s,d,r,l,p){return i(),t("div",null,[...s[0]||(s[0]=[a(`<p><code>prioricode run</code> is the agent without the theater. One prompt in, work done, exit code out. It&#39;s the same engine as the TUI — same sessions, same database, same tools — with nobody to approve things, which is exactly the part you need to understand.</p><h2 id="the-basic-move" tabindex="-1">The basic move <a class="header-anchor" href="#the-basic-move" aria-label="Permalink to &quot;The basic move&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize what changed since the last release&quot;</span></span></code></pre></div><p>Output streams to stdout as the agent works; the process exits when the session goes idle. Piped stdin is appended to the message, so:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;why did this fail?&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;explain this&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file-notes.txt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # everything after -- is passthrough args</span></span></code></pre></div><p>Run a custom <a href="./../extending/commands.html">slash command</a> instead of a raw prompt with <code>--command</code> (the message becomes its arguments):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;the auth module&quot;</span></span></code></pre></div><h2 id="options-that-matter" tabindex="-1">Options that matter <a class="header-anchor" href="#options-that-matter" aria-label="Permalink to &quot;Options that matter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>What it does</th></tr></thead><tbody><tr><td><code>-m, --model provider/model</code></td><td>override the configured model</td></tr><tr><td><code>--agent &lt;name&gt;</code></td><td>run as that agent (<code>plan</code>, <code>auto</code>, yours)</td></tr><tr><td><code>--variant</code></td><td>model variant / reasoning effort, e.g. <code>high</code></td></tr><tr><td><code>--thinking</code></td><td>show model reasoning — on by default in interactive mini mode, off in <code>run</code></td></tr><tr><td><code>-c, --continue</code> / <code>-s, --session &lt;id&gt;</code></td><td>keep talking in an existing session</td></tr><tr><td><code>--fork</code></td><td>branch instead of continuing (needs <code>--continue</code> or <code>--session</code>)</td></tr><tr><td><code>-f, --file &lt;path&gt;</code></td><td>attach files (repeatable; ≤10 MiB each)</td></tr><tr><td><code>--title &lt;name&gt;</code></td><td>name the session; empty means &quot;first 50 chars of the prompt&quot;</td></tr><tr><td><code>--share</code></td><td>auto-share the session when it&#39;s done</td></tr><tr><td><code>--command</code></td><td>run a registered command with the message as args</td></tr><tr><td><code>--format default|json</code></td><td>raw JSONL events instead of prose</td></tr><tr><td><code>--dir</code></td><td>run in another project directory</td></tr><tr><td><code>--auto</code></td><td>approve anything that would ask (see below)</td></tr><tr><td><code>--attach &lt;url&gt;</code></td><td>drive a remote server instead of running locally</td></tr><tr><td><code>--username/-u</code>, <code>--password/-p</code></td><td>basic auth for <code>--attach</code> (env: <code>PRIORICODE_SERVER_USERNAME</code>/<code>PASSWORD</code>)</td></tr></tbody></table><h2 id="json-output-for-pipelines" tabindex="-1">JSON output for pipelines <a class="header-anchor" href="#json-output-for-pipelines" aria-label="Permalink to &quot;JSON output for pipelines&quot;">​</a></h2><p><code>--format json</code> emits one JSON object per line — <code>tool_use</code>, <code>step_start</code>, <code>step_finish</code>, <code>text</code>, <code>reasoning</code>, <code>error</code> — each with its <code>sessionID</code> and timestamp. Parse it, pipe it, alert on it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bump all package versions&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;select(.type==&quot;text&quot;) | .part.text&#39;</span></span></code></pre></div><h2 id="the-permission-contract-read-this-twice" tabindex="-1">The permission contract (read this twice) <a class="header-anchor" href="#the-permission-contract-read-this-twice" aria-label="Permalink to &quot;The permission contract (read this twice)&quot;">​</a></h2><p>There is no human in a CI run. Anything that would ask is <strong>denied</strong> — <code>question</code>, <code>plan_enter</code>, and <code>plan_exit</code> are denied up front, and other asks are rejected the moment they appear. So either:</p><ol><li><strong>Pre-approve in config</strong> — narrow allow patterns (<code>&quot;bash&quot;: { &quot;bun run *&quot;: &quot;allow&quot; }</code>) committed with the repo, or passed at runtime via <code>PRIORICODE_PERMISSION</code> (a JSON ruleset); or</li><li><strong>Say <code>--auto</code></strong> — every non-denied permission is approved once, automatically. The flag&#39;s own help text calls it dangerous; believe it. The <code>auto</code> agent (<a href="./agents.html">agents</a>) is the curated version of this: no interaction, commits per verified phase.</li></ol><p>A CI job that needs no approvals on its own config is the goal. <code>--auto</code> is the shortcut, not the architecture.</p><h2 id="mini-mode-human-but-small" tabindex="-1">Mini mode: human, but small <a class="header-anchor" href="#mini-mode-human-but-small" aria-label="Permalink to &quot;Mini mode: human, but small&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mini</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # split-footer interactive session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-replay</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # skip replaying history into the new footer</span></span></code></pre></div><p>Same server, same sessions — a minimal interface for tmux panes and thin SSH. It speaks <code>/editor</code> (compose in <code>$EDITOR</code>), <code>/new</code>, and <code>/exit</code>. Replay controls: <code>--replay-limit &lt;n&gt;</code> caps how many past messages get rendered. Mini mode refuses network flags (<code>--port</code> etc.) and JSON output — it&#39;s a screen, not a pipe. (Note the spelling: <code>--mini</code> goes on the default command, not <code>run</code>.)</p><h2 id="drive-a-remote-agent-locally" tabindex="-1">Drive a remote agent locally <a class="header-anchor" href="#drive-a-remote-agent-locally" aria-label="Permalink to &quot;Drive a remote agent locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># machine A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hostname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PRIORICODE_SERVER_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">correct-horse-battery   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># before starting!</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># machine B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://machine-a:4096</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # full TUI against A&#39;s sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://machine-a:4096</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;triage the queue&quot;</span></span></code></pre></div><p>The TUI on B renders, the server on A computes — tools run where the code lives. See <a href="./../platforms/server.html">server &amp; remote</a> for auth, mDNS, and CORS.</p><h2 id="practical-patterns" tabindex="-1">Practical patterns <a class="header-anchor" href="#practical-patterns" aria-label="Permalink to &quot;Practical patterns&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nightly dependency triage, in a clean checkout, as its own project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;deps $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;update lockfiles, run tests, revert on failure&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># feed a failure to plan mode, get a written plan, no edits touched</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;propose a fix for: $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -40</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> err.log)&quot;</span></span></code></pre></div><p>Each <code>run</code> creates or continues a real session — find it later with <code>prioricode session list</code>, inspect with the <a href="./tui.html">TUI</a> or <code>/sessions</code>, and judge its work after the fact. Headless doesn&#39;t mean invisible.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./permissions.html">Permissions</a> — The full rules engine behind every decision. <ul><li><a href="./../platforms/server.html">Server</a> — Long-lived servers and the API.</li><li><a href="./../reference/cli.html">CLI reference</a> — Every <code>run</code> flag in one table.</li><li><a href="./../extending/commands.html">Custom commands</a> — Reusable prompts the pipeline can call by name.</li></ul></li></ul>`,27)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
